import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import './OldSidebar.css'; // Re-use or add specific styles here

const AutocompleteInput = ({ value, onChange, placeholder, className }) => {
    const [suggestions, setSuggestions] = useState([]);
    const [showSuggestions, setShowSuggestions] = useState(false);
    const wrapperRef = useRef(null);

    useEffect(() => {
        // Close suggestions when clicking outside
        function handleClickOutside(event) {
            if (wrapperRef.current && !wrapperRef.current.contains(event.target)) {
                setShowSuggestions(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, [wrapperRef]);

    const fetchSuggestions = async (query) => {
        if (!query || query.length < 3) {
            setSuggestions([]);
            return;
        }

        try {
            // Photon API: Free, Open Source, Good for Typeahead
            // Bias towards Bengaluru (12.97, 77.59)
            const url = `https://photon.komoot.io/api/?q=${encodeURIComponent(query)}&lat=12.97&lon=77.59&limit=5`;

            const response = await axios.get(url);

            // Photon returns GeoJSON. Features array contains the results.
            const features = response.data.features || [];

            const formattedSuggestions = features.map(f => {
                const props = f.properties;
                // Construct a display name from available properties
                const name = props.name;
                const city = props.city || props.town || props.village || props.county;
                const state = props.state;

                let displayName = name;
                if (city) displayName += `, ${city}`;
                if (state) displayName += `, ${state}`;

                return {
                    display_name: displayName,
                    name: name, // Keep raw name for input value
                    raw: props // Keep raw properties if needed
                };
            });

            setSuggestions(formattedSuggestions);
            setShowSuggestions(true);
        } catch (error) {
            console.error("Autofill Error:", error);
        }
    };

    // Debounce function
    useEffect(() => {
        const timer = setTimeout(() => {
            if (value) {
                fetchSuggestions(value);
            }
        }, 300); // Reduced delay for faster feel

        return () => clearTimeout(timer);
    }, [value]);

    const handleSelect = (suggestion) => {
        onChange(suggestion.name);
        setShowSuggestions(false);
    };

    return (
        <div className="autocomplete-wrapper" ref={wrapperRef} style={{ position: 'relative', width: '100%' }}>
            <input
                type="text"
                className={className}
                placeholder={placeholder}
                value={value}
                onChange={(e) => onChange(e.target.value)}
                onFocus={() => value && value.length >= 3 && setShowSuggestions(true)}
            />
            {showSuggestions && suggestions.length > 0 && (
                <ul className="suggestions-list">
                    {suggestions.map((s, index) => (
                        <li key={index} onClick={() => handleSelect(s)}>
                            <strong>{s.name}</strong>
                            <br />
                            <small>{s.display_name}</small>
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
};

export default AutocompleteInput;
